package skillbridge;

import java.sql.SQLException;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.stream.*;
import static skillbridge.Database.*;

/** Escaped, accessible server-rendered views. No third-party frontend resources. */
public final class Views {
    private final Database db;
    private final Workflow flow;
    private static final String[] LEVEL={"Not added","Beginner","Intermediate","Advanced"};
    private static final List<String> STATUSES=List.of("APPLIED","SHORTLISTED","INTERVIEW","OFFERED","ACCEPTED","DECLINED","REJECTED","WITHDRAWN");
    public Views(Database db,Workflow flow){this.db=db;this.flow=flow;}
    static String e(Object value){return String.valueOf(value==null?"":value).replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}
    static String f(double n){return String.format(Locale.ROOT,"%.1f",n);}
    static String pct(double n){return f(n*100)+"%";}
    static String pretty(Object x){return e(String.valueOf(x).replace('_',' ').toLowerCase(Locale.ROOT));}
    static String hidden(String key,Object value){return "<input type='hidden' name='"+e(key)+"' value='"+e(value)+"'>";}
    static String form(String action,String csrf){return "<form method='post' action='"+e(action)+"'>"+hidden("csrf",csrf);}
    static String badge(Object status){return "<span class='badge status-"+e(status)+"'>"+pretty(status)+"</span>";}
    static String link(String url,String label){return "<a href='"+e(url)+"'>"+e(label)+"</a>";}
    static String button(String url,String label){return "<a class='button' href='"+e(url)+"'>"+e(label)+"</a>";}
    static String empty(String title,String description,String action){return "<div class='empty'><h3>"+e(title)+"</h3><p>"+e(description)+"</p>"+action+"</div>";}
    static String heading(String eyebrow,String title,String detail,String action){return "<header class='page-heading'><div><p class='eyebrow'>"+e(eyebrow)+"</p><h1>"+e(title)+"</h1><p class='muted'>"+e(detail)+"</p></div><div>"+action+"</div></header>";}
    static String field(String label,String name,Object value,String type,boolean required,String attrs){return "<label>"+e(label)+"<input type='"+type+"' name='"+name+"' value='"+e(value)+"' "+(required?"required ":"")+attrs+"></label>";}
    static String area(String label,String name,Object value,int max,boolean required){return "<label>"+e(label)+"<textarea name='"+name+"' maxlength='"+max+"' rows='5' "+(required?"required":"")+">"+e(value)+"</textarea></label>";}
    static String select(String label,String name,Object chosen,List<String> values){StringBuilder b=new StringBuilder("<label>"+e(label)+"<select name='"+e(name)+"'>");for(String value:values)b.append("<option value='").append(e(value)).append("'").append(value.equals(String.valueOf(chosen))?" selected":"").append(">").append(value.isEmpty()?"All":pretty(value)).append("</option>");return b.append("</select></label>").toString();}
    static String metric(String label,Object value,String sub){return "<div class='metric'><span>"+e(label)+"</span><strong>"+e(value)+"</strong><small>"+e(sub)+"</small></div>";}
    static String date(Object value){if(value instanceof java.sql.Timestamp t)return t.toLocalDateTime().format(DateTimeFormatter.ofPattern("dd MMM yyyy, HH:mm"));if(value instanceof java.sql.Date d)return d.toLocalDate().format(DateTimeFormatter.ofPattern("dd MMM yyyy"));return e(value);}
    static String doc(String title,String body){return "<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>"+e(title)+" · SkillBridge</title><link rel='stylesheet' href='/style.css'></head><body>"+body+"</body></html>";}
    public static String error(int code,String message){return doc("Request not completed","<main class='error-page'><a class='brand' href='/'>SB <span>SkillBridge</span></a><p class='eyebrow'>Request "+code+"</p><h1>Let's get you back on track.</h1><p>"+e(message)+"</p><p>"+button("/","Back to overview")+" "+link("/login","Sign in")+"</p><p class='muted'>Use your browser's Back button to return to the form. Refresh if your session or form has expired.</p></main>");}
    public String layout(Map<String,Object> user,String title,String path,String body,String csrf,String message)throws SQLException{
        boolean admin="ADMIN".equals(user.get("role"));long uid=number(user,"id");
        long unread=number(db.one("SELECT COUNT(*) AS n FROM notifications WHERE user_id=? AND is_read=FALSE",uid),"n");
        String[][] nav=admin?new String[][]{{"/","Overview"},{"/opportunities","Opportunities"},{"/applications","Application desk"},{"/admin/students","Students"},{"/admin/skills","Skill catalogue"},{"/analytics","Probability lab"},{"/reports","Reports"},{"/admin/audit","Activity log"},{"/profile","Account"}}:new String[][]{{"/","Overview"},{"/opportunities","Find opportunities"},{"/applications","My applications"},{"/saved","Saved opportunities"},{"/profile","My profile"},{"/analytics","Probability lab"},{"/reports","Reports"}};
        StringBuilder side=new StringBuilder("<aside class='sidebar'><a class='brand' href='/'><b>SB</b><span>SkillBridge<small>Campus placement portal</small></span></a><p class='nav-caption'>"+(admin?"PLACEMENT OFFICE":"STUDENT WORKSPACE")+"</p><nav aria-label='Main navigation'>");
        for(String[] item:nav)side.append("<a href='").append(item[0]).append("' ").append(path.equals(item[0])?"class='active' aria-current='page'":"").append(">").append(item[1]).append("</a>");
        side.append("</nav><div class='sidebar-bottom'><strong>").append(e(user.get("full_name"))).append("</strong><small>").append(e(user.get("email"))).append("</small>").append(form("/logout",csrf)).append("<button class='text-button'>Sign out</button></form></div></aside>");
        return doc(title,"<a class='skip-link' href='#main'>Skip to content</a>"+side+"<div class='workspace'><div class='topbar'><span>Academic year "+LocalDate.now().getYear()+"–"+(LocalDate.now().getYear()+1)+"</span><a href='/notifications'>Notifications <span class='counter'>"+unread+"</span></a></div><main id='main'>"+(!message.isBlank()?"<div class='notice' role='status'>"+e(message)+"</div>":"")+body+"</main><footer>SkillBridge · Placement &amp; student development <span>All times: server local time</span></footer></div>");
    }
    public String auth(boolean register,String csrf,String message){
        String fields=register?field("Full name","name","","text",true,"minlength='2' maxlength='100' autocomplete='name'")+field("Department","department","","text",true,"maxlength='100'")+field("Graduation year","year",LocalDate.now().getYear()+1,"number",true,"min='2000' max='2100'"):"";
        fields+=field("Email address","email","","email",true,"maxlength='180' autocomplete='username'")+field("Password","password","","password",true,"minlength='10' maxlength='128' autocomplete='"+(register?"new-password":"current-password")+"'");
        return doc(register?"Create student account":"Sign in","<main class='auth-page'><section class='auth-intro'><a class='brand' href='/'>SB <span>SkillBridge</span></a><p class='eyebrow'>YOUR NEXT CHAPTER</p><h1>Find the right role.<br>Build your way there.</h1><p>A shared workspace for students and the placement office. Discover opportunities, understand your skill gaps and keep every application in one place.</p><div class='auth-note'><strong>One profile. A clearer path.</strong><p>Track progress from your first application to your final offer.</p></div></section><section class='auth-form'><p class='eyebrow'>CAMPUS PLACEMENTS</p><h2>"+(register?"Create your student account":"Welcome back")+"</h2><p class='muted'>"+(register?"Start with the basics. You can add skills after signing up.":"Sign in to continue to your workspace.")+"</p>"+(!message.isBlank()?"<div class='notice'>"+e(message)+"</div>":"")+form(register?"/register":"/login",csrf)+fields+(register?"<p class='hint'>Use at least 10 characters with a letter and a number.</p>":"")+"<button class='wide'>"+(register?"Create account":"Sign in")+"</button></form><p>"+(register?"Already registered? "+link("/login","Sign in"):"New here? "+link("/register","Create a student account"))+"</p><details><summary>Local demonstration accounts</summary><p>Student: student@skillbridge.local<br>Student@12345</p><p>Placement office: admin@skillbridge.local<br>Admin@12345</p><small>Demo use only. Change passwords before real use.</small></details></section></main>");
    }
    public String dashboard(Map<String,Object> user,String csrf)throws Exception{
        boolean admin="ADMIN".equals(user.get("role"));long uid=number(user,"id");
        String name=user.get("full_name").toString().split(" ")[0];
        StringBuilder b=new StringBuilder(heading(admin?"PLACEMENT OFFICE":"YOUR WORKSPACE",admin?"Placement overview":"Good to see you, "+name,admin?"A practical view of your campus recruitment pipeline.":"Keep your profile current, find a role and follow your progress.",button(admin?"/admin/opportunity":"/opportunities",admin?"Post opportunity":"Find opportunities")));
        long open=number(db.one("SELECT COUNT(*) AS n FROM opportunities WHERE status='OPEN' AND deadline>=CURRENT_DATE"),"n");
        String scope=admin?"":" WHERE user_id="+uid;
        long total=number(db.one("SELECT COUNT(*) AS n FROM applications"+scope),"n");
        long offers=number(db.one("SELECT COUNT(*) AS n FROM applications WHERE status IN ('OFFERED','ACCEPTED','DECLINED')"+(admin?"":" AND user_id="+uid)),"n");
        long interviews=number(db.one("SELECT COUNT(*) AS n FROM applications WHERE status='INTERVIEW'"+(admin?"":" AND user_id="+uid)),"n");
        b.append("<div class='metrics'>").append(metric("Open opportunities",open,"Within the application deadline")).append(metric("Applications",total,admin?"Across all students":"Submitted by you")).append(metric("Interview stage",interviews,"Current pipeline")).append(metric("Offers received",offers,"Includes accepted and declined")).append("</div>");
        if(admin){b.append("<section class='panel'><div class='section-title'><h2>Pipeline at a glance</h2>").append(link("/applications","Open application desk →")).append("</div><div class='pipeline'>");for(String status:STATUSES){long count=number(db.one("SELECT COUNT(*) AS n FROM applications WHERE status=?",status),"n");b.append("<div>").append(badge(status)).append("<strong>").append(count).append("</strong></div>");}b.append("</div></section>");
            b.append("<div class='split'><section class='panel'><h2>Office checklist</h2><ol class='checklist'><li>Publish roles with clear eligibility and skill requirements.</li><li>Review applications and record every decision.</li><li>Schedule interviews before issuing offers.</li><li>Use outcome statistics only when completed outcomes exist.</li></ol></section><section class='panel'><h2>Quick access</h2><div class='quick-links'>").append(link("/admin/students","Student directory →")).append(link("/reports","Export applications →")).append(link("/admin/audit","Review activity log →")).append("</div></section></div>");
        }else{
            int skillCount=flow.levels(uid,true).size();
            if(skillCount==0||((Number)user.get("cgpa")).doubleValue()==0)b.append("<div class='notice'><strong>Your profile needs a little work.</strong> Add your CGPA and skills before applying. ").append(link("/profile","Complete profile →")).append("</div>");
            var meetings=db.query("SELECT a.id,a.interview_at,a.interview_location,o.company,o.title FROM applications a JOIN opportunities o ON o.id=a.opportunity_id WHERE a.user_id=? AND a.status='INTERVIEW' ORDER BY a.interview_at",uid);
            if(!meetings.isEmpty()){b.append("<section class='panel'><h2>Your interviews</h2>");for(var m:meetings)b.append("<p>").append(link("/application?id="+m.get("id"),m.get("company")+" · "+m.get("title"))).append("<br><span class='muted'>").append(date(m.get("interview_at"))).append(" · ").append(e(m.get("interview_location"))).append("</span></p>");b.append("</section>");}
            b.append("<section class='section-title'><div><h2>Recommended for your skills</h2><p class='muted'>Ranked by current prerequisite coverage, not hiring likelihood.</p></div>").append(link("/opportunities?sort=match","View all →")).append("</section><div class='job-grid'>");
            var jobs=db.query("SELECT * FROM opportunities WHERE status='OPEN' AND deadline>=CURRENT_DATE");Map<Long,Double> scores=new HashMap<>();for(var j:jobs)scores.put(number(j,"id"),flow.score(uid,number(j,"id")));jobs.sort(Comparator.comparingDouble((Map<String,Object> j)->scores.get(number(j,"id"))).reversed());int shown=0;
            for(var j:jobs)if(Workflow.eligibility(user,j).isEmpty()&&shown++<3)b.append(jobCard(user,j,scores.get(number(j,"id"))));
            if(shown==0)b.append(empty("No eligible roles yet","Update your profile or browse all roles to see their requirements.",button("/opportunities","Browse roles")));
            b.append("</div><section class='panel'><h2>A useful distinction</h2><p>A 90% skill coverage score means your recorded skills cover 90% of the stated prerequisites. It does <strong>not</strong> mean a 90% chance of getting hired. The probability lab keeps these ideas separate.</p></section>");
        }return b.toString();
    }
    private String jobCard(Map<String,Object> user,Map<String,Object> j,double score){
        boolean admin="ADMIN".equals(user.get("role"));String reason=admin?"":Workflow.eligibility(user,j);
        String money=String.format(Locale.ROOT,"%,d",number(j,"compensation"));
        return "<article class='job-card'><div class='job-top'><span class='company-mark'>"+e(j.get("company").toString().substring(0,1))+"</span>"+badge(j.get("kind"))+"</div><p class='muted company'>"+e(j.get("company"))+"</p><h3>"+link("/opportunity?id="+j.get("id"),j.get("title").toString())+"</h3><p class='muted'>"+e(j.get("location"))+" · "+"INR "+money+("INTERNSHIP".equals(j.get("kind"))?" / month":" / year")+"</p><div class='job-meta'><span>Min. CGPA "+e(j.get("min_cgpa"))+"</span><span>Batch "+e(j.get("graduation_year"))+"</span></div><p class='small'>Apply by "+date(j.get("deadline"))+"</p>"+(admin?badge(j.get("status")):"<div class='match-line'><strong>"+f(score)+"%</strong><span>skill coverage</span></div><p class='small "+(reason.isEmpty()?"success-text":"muted")+"'>"+(reason.isEmpty()?"Eligible to apply":e(reason))+"</p>")+"<a class='card-link' href='/opportunity?id="+j.get("id")+"'>View role <span>→</span></a></article>";
    }
    public String opportunities(Map<String,Object> user,String csrf,Map<String,String> p)throws Exception{
        boolean admin="ADMIN".equals(user.get("role")),saved=p.containsKey("saved");long uid=number(user,"id");String q=p.getOrDefault("q","").trim(),kind=p.getOrDefault("kind",""),sort=p.getOrDefault("sort","deadline"),status=p.getOrDefault("state","OPEN");
        if(q.length()>150)throw new IllegalArgumentException("Search must be 150 characters or fewer.");
        StringBuilder b=new StringBuilder(heading("OPPORTUNITY BOARD",saved?"Your saved roles":"Find your next opportunity","Explore roles, compare requirements and apply with your student profile.",admin?button("/admin/opportunity","Post opportunity"):""));
        b.append("<form class='filter-bar' method='get' action='").append(saved?"/saved":"/opportunities").append("'>").append(field("Search title, company or location","q",q,"search",false,"maxlength='150' placeholder='e.g. Java, Chennai'")).append(select("Type","kind",kind,List.of("","INTERNSHIP","PLACEMENT","FULL_TIME"))).append(select("Status","state",status,List.of("OPEN","CLOSED","ALL"))).append(select("Sort by","sort",sort,admin?List.of("deadline","newest"):List.of("deadline","newest","match"))).append("<button>Search</button></form>");
        var jobs=db.query("SELECT o.* FROM opportunities o"+(saved?" JOIN saved_opportunities s ON s.opportunity_id=o.id AND s.user_id="+uid:"")+" ORDER BY o.deadline,o.id");
        String search=q.toLowerCase(Locale.ROOT);jobs.removeIf(j->(!search.isBlank()&&!(j.get("title")+" "+j.get("company")+" "+j.get("location")).toLowerCase(Locale.ROOT).contains(search))||(!kind.isBlank()&&!kind.equals(j.get("kind")))||(!status.equals("ALL")&&!(status.equals("OPEN")?j.get("status").equals("OPEN")&&!((java.sql.Date)j.get("deadline")).toLocalDate().isBefore(LocalDate.now()):j.get("status").equals("CLOSED")||((java.sql.Date)j.get("deadline")).toLocalDate().isBefore(LocalDate.now()))));
        Map<Long,Double> scores=new HashMap<>();if(!admin)for(var j:jobs)scores.put(number(j,"id"),flow.score(uid,number(j,"id")));
        if(sort.equals("newest"))jobs.sort(Comparator.comparingLong((Map<String,Object> j)->number(j,"id")).reversed());
        if(sort.equals("match")&&!admin)jobs.sort(Comparator.comparingDouble((Map<String,Object> j)->scores.get(number(j,"id"))).reversed());
        int pages=Math.max(1,(jobs.size()+8)/9),page=App.integerDefault(p,"page",1,1,100000);page=Math.min(page,pages);
        b.append("<p class='muted'>").append(jobs.size()).append(" role").append(jobs.size()==1?"":"s").append(" found · Page ").append(page).append(" of ").append(pages).append("</p>");
        if(jobs.isEmpty())b.append(empty(saved?"Nothing saved yet":"No matching opportunities",saved?"Save a role from its details page to return to it later.":"Try a different search or change the status filter.",saved?button("/opportunities","Find opportunities"):""));
        else{b.append("<div class='job-grid'>");for(var j:jobs.subList((page-1)*9,Math.min(page*9,jobs.size())))b.append(jobCard(user,j,admin?0:scores.get(number(j,"id"))));b.append("</div>");}
        String base=(saved?"/saved":"/opportunities")+"?q="+App.enc(q)+"&kind="+App.enc(kind)+"&state="+App.enc(status)+"&sort="+App.enc(sort)+"&page=";
        if(pages>1)b.append("<div class='pagination'>").append(page>1?button(base+(page-1),"← Previous"):"").append(page<pages?button(base+(page+1),"Next →"):"").append("</div>");return b.toString();
    }
    public String opportunity(Map<String,Object> user,String csrf,long oid)throws Exception{
        var job=db.one("SELECT * FROM opportunities WHERE id=?",oid);if(job==null)throw new App.HttpError(404,"Opportunity not found.");
        boolean admin="ADMIN".equals(user.get("role"));long uid=number(user,"id");
        StringBuilder b=new StringBuilder(heading(job.get("company").toString(),job.get("title").toString(),job.get("location")+" · "+job.get("kind").toString().replace('_',' '),admin?button("/admin/opportunity?id="+oid,"Edit opportunity"):""));
        b.append("<div class='detail-grid'><section class='panel'><div class='inline'>").append(badge(job.get("status"))).append("<span class='muted'>Closes ").append(date(job.get("deadline"))).append("</span></div><h2>About the role</h2><p class='preline'>").append(e(job.get("description"))).append("</p><h2>Requirements and skill gaps</h2><div class='table-wrap'><table><thead><tr><th>Skill</th><th>Required level</th>").append(admin?"":"<th>Your level</th><th>Coverage</th>").append("</tr></thead><tbody>");
        var owned=admin?Map.<Long,Integer>of():flow.levels(uid,true);
        for(var r:db.query("SELECT s.id,s.name,os.min_level FROM opportunity_skills os JOIN skills s ON s.id=os.skill_id WHERE os.opportunity_id=? ORDER BY s.name",oid)){
            int required=((Number)r.get("min_level")).intValue(),have=owned.getOrDefault(number(r,"id"),0);
            b.append("<tr><td>").append(e(r.get("name"))).append("</td><td>").append(LEVEL[required]).append("</td>");if(!admin)b.append("<td>").append(LEVEL[have]).append("</td><td>").append(have>=required?"Met":have==0?"Missing skill":"Improve proficiency").append("</td>");b.append("</tr>");
        }
        b.append("</tbody></table></div><p class='hint'>Beginner = 1, intermediate = 2, advanced = 3. Partial proficiency earns proportional coverage. Skills do not block an application; academic eligibility does.</p></section><aside><section class='panel'><h2>Role at a glance</h2><dl><dt>Compensation</dt><dd>INR ").append(String.format(Locale.ROOT,"%,d",number(job,"compensation"))).append(" / ").append("INTERNSHIP".equals(job.get("kind"))?"month":"year").append("</dd><dt>Minimum CGPA</dt><dd>").append(e(job.get("min_cgpa"))).append(" / 10</dd><dt>Graduation batch</dt><dd>").append(job.get("graduation_year")).append("</dd></dl>");
        if(!admin){boolean saved=db.one("SELECT user_id FROM saved_opportunities WHERE user_id=? AND opportunity_id=?",uid,oid)!=null;b.append("<div class='match-large'>").append(f(flow.score(uid,oid))).append("%<small>current skill coverage</small></div>").append(form("/save",csrf)).append(hidden("opportunity",oid)).append("<button class='secondary wide'>").append(saved?"Remove from saved":"Save for later").append("</button></form>");}
        b.append("</section></aside></div>");
        if(!admin){var application=db.one("SELECT id,status FROM applications WHERE user_id=? AND opportunity_id=?",uid,oid);String reason=Workflow.eligibility(user,job);
            if(application!=null)b.append("<section class='panel'><h2>You have applied</h2>").append(badge(application.get("status"))).append("<p>").append(button("/application?id="+application.get("id"),"View application and timeline")).append("</p></section>");
            else if(!reason.isEmpty())b.append("<div class='notice warning'>").append(e(reason)).append(" ").append(link("/profile","Review profile")).append("</div>");
            else b.append("<section class='panel'><h2>Apply for this role</h2><p class='muted'>Your academic details, portfolio link and skill levels will be captured at submission. You can submit only once per role.</p>").append(form("/apply",csrf)).append(hidden("opportunity",oid)).append(area("Why are you interested?","cover_letter","",3000,true)).append("<p class='hint'>Do not include passwords, government IDs or other sensitive information.</p><button>Submit application</button></form></section>");
        }else b.append(button("/applications?opportunity="+oid,"Review applicants"));return b.toString();
    }
    private String applicationsSql(){return "SELECT a.*,u.full_name,u.email,o.title,o.company FROM applications a JOIN users u ON u.id=a.user_id JOIN opportunities o ON o.id=a.opportunity_id";}
    public String applications(Map<String,Object> user,Map<String,String> p)throws Exception{
        boolean admin="ADMIN".equals(user.get("role"));String status=p.getOrDefault("status","");long uid=number(user,"id");
        String sql=applicationsSql()+(admin?" WHERE 1=1":" WHERE a.user_id="+uid);List<Object> args=new ArrayList<>();
        if(!status.isBlank()){sql+=" AND a.status=?";args.add(status);}
        if(p.containsKey("opportunity")){sql+=" AND a.opportunity_id=?";args.add(App.id(p,"opportunity"));}
        var rows=db.query(sql+" ORDER BY a.updated_at DESC,a.id DESC",args.toArray());
        StringBuilder b=new StringBuilder(heading(admin?"PLACEMENT OFFICE":"YOUR PROGRESS",admin?"Application desk":"My applications",admin?"Review applicants, record decisions and arrange interviews.":"Every submission, interview and decision in one place.",button("/reports/applications.csv","Export CSV")));
        List<String> options=new ArrayList<>();options.add("");options.addAll(STATUSES);
        b.append("<form class='filter-bar' method='get'>").append(select("Application status","status",status,options)).append(p.containsKey("opportunity")?hidden("opportunity",p.get("opportunity")):"").append("<button>Filter</button></form>");
        if(rows.isEmpty())return b.append(empty("No applications to show",admin?"Student submissions will appear here.":"Find a suitable role and submit your first application.",admin?"":button("/opportunities","Browse opportunities"))).toString();
        b.append("<section class='panel table-wrap'><table><thead><tr><th>Application</th>").append(admin?"<th>Student</th>":"").append("<th>Role / company</th><th>Status</th><th>Coverage</th><th>Updated</th></tr></thead><tbody>");
        for(var r:rows)b.append("<tr><td>").append(link("/application?id="+r.get("id"),"#"+r.get("id"))).append("</td>").append(admin?"<td>"+e(r.get("full_name"))+"<small>"+e(r.get("email"))+"</small></td>":"").append("<td>").append(e(r.get("title"))).append("<small>").append(e(r.get("company"))).append("</small></td><td>").append(badge(r.get("status"))).append("</td><td>").append(f(((Number)r.get("score_at_apply")).doubleValue())).append("%</td><td>").append(date(r.get("updated_at"))).append("</td></tr>");
        return b.append("</tbody></table></section><p class='hint'>Coverage is frozen at submission, so later profile edits do not change an existing application.</p>").toString();
    }
    public String application(Map<String,Object> user,String csrf,long id)throws Exception{
        var a=db.one(applicationsSql()+" WHERE a.id=?",id);boolean admin="ADMIN".equals(user.get("role"));long uid=number(user,"id");
        if(a==null||(!admin&&number(a,"user_id")!=uid))throw new App.HttpError(404,"Application not found.");
        String status=a.get("status").toString();StringBuilder b=new StringBuilder(heading("APPLICATION #"+id,a.get("title").toString(),a.get("company")+" · Submitted "+date(a.get("created_at")),badge(status)));
        b.append("<div class='detail-grid'><div><section class='panel'><h2>Application details</h2><p><strong>").append(e(a.get("full_name"))).append("</strong><br>").append(e(a.get("email"))).append("</p><p>Skill coverage at submission: <strong>").append(f(((Number)a.get("score_at_apply")).doubleValue())).append("%</strong></p><h3>Cover note</h3><p class='preline'>").append(e(a.get("cover_letter"))).append("</p><details><summary>Profile snapshot at submission</summary><p class='preline'>").append(e(a.get("profile_snapshot"))).append("</p></details><p>").append(link("/opportunity?id="+a.get("opportunity_id"),"View opportunity →")).append("</p></section>");
        if(a.get("interview_at")!=null)b.append("<section class='panel'><h2>Interview details</h2><p><strong>").append(date(a.get("interview_at"))).append("</strong><br>").append(e(a.get("interview_location"))).append("</p><p class='hint'>Times are shown in the server's local timezone. Confirm the timezone with your placement office.</p></section>");
        List<String> next=admin?Workflow.TRANSITIONS.getOrDefault(status,List.of()).stream().filter(s->!List.of("ACCEPTED","DECLINED").contains(s)).toList():status.equals("OFFERED")?List.of("ACCEPTED","DECLINED"):List.of("APPLIED","SHORTLISTED","INTERVIEW").contains(status)?List.of("WITHDRAWN"):List.of();
        if(!next.isEmpty()){
            b.append("<section class='panel'><h2>").append(admin?"Record a decision":"Available actions").append("</h2>").append(form(admin?"/admin/status":"/status",csrf)).append(hidden("application",id)).append(hidden("version",a.get("version"))).append(select("New status","status",next.get(0),next));
            if(admin)b.append(field("Interview date and time (required when moving to interview)","interview_at","","datetime-local",false,"")).append(field("Interview venue / meeting link","location","","text",false,"maxlength='300'"));
            b.append(area("Note (visible to the student)","note","",1000,false)).append("<label class='check'><input type='checkbox' name='confirm' required> I have checked this decision. Terminal decisions cannot be reversed in this portal.</label><button>").append(admin?"Save decision":"Confirm action").append("</button></form></section>");
        }
        b.append("</div><aside class='panel timeline-panel'><h2>Status timeline</h2><ol class='timeline'>");
        for(var r:db.query("SELECT ev.*,u.full_name FROM application_events ev JOIN users u ON u.id=ev.actor_id WHERE application_id=? ORDER BY ev.created_at,ev.id",id))b.append("<li>").append(badge(r.get("status"))).append("<p class='preline'>").append(e(r.get("note"))).append("</p><small>").append(e(r.get("full_name"))).append("<br>").append(date(r.get("created_at"))).append("</small></li>");
        return b.append("</ol></aside></div>").toString();
    }
    public String profile(Map<String,Object> u,String csrf)throws Exception{
        boolean admin="ADMIN".equals(u.get("role"));StringBuilder b=new StringBuilder(heading("ACCOUNT",admin?"Account settings":"My student profile",admin?"Keep your placement-office account secure.":"Your academic details and recorded skills help explain your fit for each role.",""));
        if(!admin){b.append("<section class='panel'>").append(form("/profile",csrf)).append("<h2>Personal and academic details</h2><div class='form-grid'>").append(field("Full name","name",u.get("full_name"),"text",true,"minlength='2' maxlength='100'")).append(field("Department","department",u.get("department"),"text",true,"minlength='2' maxlength='100'")).append(field("CGPA (out of 10)","cgpa",u.get("cgpa"),"number",true,"min='0' max='10' step='0.01'")).append(field("Graduation year","year",u.get("graduation_year"),"number",true,"min='2000' max='2100'")).append("</div>").append(field("Portfolio or resume link (optional)","portfolio",u.get("portfolio"),"url",false,"maxlength='400' placeholder='https://…'")).append("<p class='hint'>Use a view-only portfolio or resume link. This version does not store uploaded documents.</p>").append(area("Short introduction","bio",u.get("bio"),1500,false)).append("<h2>Skills and proficiency</h2><p class='muted'>Be accurate: beginner = learning, intermediate = can work independently, advanced = can design and mentor.</p>").append(skillFields(flow.levels(number(u,"id"),true))).append("<button>Save profile</button></form></section>");}
        b.append("<section class='panel'><h2>Change password</h2>").append(form("/password",csrf)).append(field("Current password","current_password","","password",true,"maxlength='128' autocomplete='current-password'")).append(field("New password","new_password","","password",true,"minlength='10' maxlength='128' autocomplete='new-password'")).append("<p class='hint'>10–128 characters, including a letter and a number.</p><button class='secondary'>Update password</button></form></section>");return b.toString();
    }
    private String skillFields(Map<Long,Integer> values)throws SQLException{
        StringBuilder b=new StringBuilder("<div class='skill-grid'>");for(var s:db.query("SELECT * FROM skills ORDER BY name")){long id=number(s,"id");b.append("<label>").append(e(s.get("name"))).append("<select name='skill_").append(id).append("'>");for(int i=0;i<=3;i++)b.append("<option value='").append(i).append("'").append(values.getOrDefault(id,0)==i?" selected":"").append(">").append(LEVEL[i]).append("</option>");b.append("</select></label>");}return b.append("</div>").toString();
    }
    public String opportunityForm(long id,String csrf)throws Exception{
        Map<String,Object> j=id==0?Map.of():db.one("SELECT * FROM opportunities WHERE id=?",id);if(j==null)throw new App.HttpError(404,"Opportunity not found.");
        StringBuilder b=new StringBuilder(heading("PLACEMENT OFFICE",id==0?"Post an opportunity":"Edit opportunity","Make the requirements clear. Existing applications keep their submission-time snapshot.",""));
        b.append("<section class='panel'>").append(form("/admin/opportunity",csrf)).append(hidden("id",id==0?"":id)).append("<div class='form-grid'>").append(field("Role title","title",j.getOrDefault("title",""),"text",true,"minlength='3' maxlength='150'")).append(field("Company","company",j.getOrDefault("company",""),"text",true,"minlength='2' maxlength='150'")).append(select("Opportunity type","kind",j.getOrDefault("kind","INTERNSHIP"),List.of("INTERNSHIP","PLACEMENT","FULL_TIME"))).append(field("Location / Remote","location",j.getOrDefault("location",""),"text",true,"minlength='2' maxlength='100'")).append(field("Compensation in INR (monthly for internship; annual otherwise)","compensation",j.getOrDefault("compensation",0),"number",true,"min='0' max='100000000'")).append(field("Minimum CGPA","cgpa",j.getOrDefault("min_cgpa",6),"number",true,"min='0' max='10' step='0.01'")).append(field("Graduation batch","year",j.getOrDefault("graduation_year",LocalDate.now().getYear()+1),"number",true,"min='2000' max='2100'")).append(field("Application deadline","deadline",j.getOrDefault("deadline",LocalDate.now().plusDays(30)),"date",true,"")).append(select("Availability","status",j.getOrDefault("status","OPEN"),List.of("OPEN","CLOSED"))).append("</div>").append(area("Role description","description",j.getOrDefault("description",""),6000,true)).append("<h2>Required skills</h2><p class='hint'>Choose at least one. Not added means the skill is not a requirement.</p>").append(skillFields(id==0?Map.of():flow.levels(id,false))).append("<button>Save opportunity</button></form></section>");return b.toString();
    }
    public String notifications(long uid,String csrf)throws Exception{
        var rows=db.query("SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC,id DESC",uid);StringBuilder b=new StringBuilder(heading("INBOX","Your notifications","Submission confirmations, recruitment decisions and interview updates.",""));
        if(rows.isEmpty())return b.append(empty("You're all caught up","Your application updates will appear here.","")).toString();
        b.append(form("/notifications/read",csrf)).append("<button class='secondary'>Mark all as read</button></form><section class='panel notice-list'>");
        for(var r:rows)b.append("<article class='").append(Boolean.TRUE.equals(r.get("is_read"))?"read":"unread").append("'><div>").append(link(r.get("link").toString(),r.get("message").toString())).append("<small>").append(date(r.get("created_at"))).append("</small></div><span>").append(Boolean.TRUE.equals(r.get("is_read"))?"Read":"New").append("</span></article>");return b.append("</section>").toString();
    }
    public String students(Map<String,String> p)throws Exception{
        String q=p.getOrDefault("q","").toLowerCase(Locale.ROOT);var rows=db.query("SELECT u.id,u.full_name,u.email,u.department,u.cgpa,u.graduation_year,(SELECT COUNT(*) FROM student_skills s WHERE s.user_id=u.id) AS skill_count,(SELECT COUNT(*) FROM applications a WHERE a.user_id=u.id) AS application_count FROM users u WHERE role='STUDENT' ORDER BY u.full_name");rows.removeIf(r->!(r.get("full_name")+" "+r.get("department")+" "+r.get("email")).toLowerCase(Locale.ROOT).contains(q));
        StringBuilder b=new StringBuilder(heading("PLACEMENT OFFICE","Student directory","Academic profiles and participation at a glance. Passwords are never displayed.",""));b.append("<form class='filter-bar'>").append(field("Search students","q",q,"search",false,"maxlength='150'")).append("<button>Search</button></form>");
        if(rows.isEmpty())return b.append(empty("No students found","Try a different search.","")).toString();
        b.append("<section class='panel table-wrap'><table><thead><tr><th>Student</th><th>Department</th><th>CGPA</th><th>Batch</th><th>Skills</th><th>Applications</th></tr></thead><tbody>");for(var r:rows)b.append("<tr><td>").append(e(r.get("full_name"))).append("<small>").append(e(r.get("email"))).append("</small></td><td>").append(e(r.get("department"))).append("</td><td>").append(e(r.get("cgpa"))).append("</td><td>").append(r.get("graduation_year")).append("</td><td>").append(r.get("skill_count")).append("</td><td>").append(r.get("application_count")).append("</td></tr>");return b.append("</tbody></table></section>").toString();
    }
    public String skills(String csrf)throws Exception{
        StringBuilder b=new StringBuilder(heading("PLACEMENT OFFICE","Skill catalogue","A shared vocabulary for student profiles and opportunity requirements.",""));
        b.append("<div class='split'><section class='panel'><h2>Add a skill</h2>").append(form("/admin/skill",csrf)).append(field("Skill name","name","","text",true,"maxlength='80'")).append("<button>Add to catalogue</button></form><p class='hint'>Existing skill names are retained so application snapshots remain interpretable.</p></section><section class='panel'><h2>Current catalogue</h2><div class='tags'>");
        for(var s:db.query("SELECT * FROM skills ORDER BY name"))b.append("<span class='tag'>#").append(s.get("id")).append(" · ").append(e(s.get("name"))).append("</span>");return b.append("</div></section></div>").toString();
    }
    public String audit()throws SQLException{
        StringBuilder b=new StringBuilder(heading("ACCOUNTABILITY","Activity log","The 200 most recent recorded changes. Application timelines retain the full decision history.",""));b.append("<section class='panel table-wrap'><table><thead><tr><th>When</th><th>Actor</th><th>Action</th><th>Record</th><th>Detail</th></tr></thead><tbody>");
        for(var r:db.query("SELECT a.*,u.full_name FROM audit_log a JOIN users u ON u.id=a.actor_id ORDER BY a.id DESC FETCH FIRST 200 ROWS ONLY"))b.append("<tr><td>").append(date(r.get("created_at"))).append("</td><td>").append(e(r.get("full_name"))).append("</td><td>").append(pretty(r.get("action"))).append("</td><td>#").append(r.get("entity_id")).append("</td><td>").append(e(r.get("detail"))).append("</td></tr>");return b.append("</tbody></table></section>").toString();
    }
    public String reports(boolean admin){return heading("DATA EXPORTS","Reports","Download a spreadsheet-compatible report of "+(admin?"all campus applications.":"your own applications."),"")+"<section class='panel'><h2>Application register</h2><p>Includes student name, email, opportunity, company, current status, submission-time coverage and timestamp. Rows are restricted by account role.</p>"+button("/reports/applications.csv","Download applications.csv")+"<p class='hint'>CSV values are quoted, escaped and protected against common spreadsheet formula injection.</p></section><section class='panel'><h2>Need the underlying reasoning?</h2><p>The probability lab explains each statistic and separates prerequisite coverage from observed offer outcomes.</p>"+link("/analytics","Open probability lab →")+"</section>";}
    public String analytics(Map<String,Object> user,Map<String,String> p)throws Exception{
        boolean admin="ADMIN".equals(user.get("role"));double threshold=p.containsKey("threshold")?App.decimal(p,"threshold",0,100):60;
        var students=admin?db.query("SELECT id FROM users WHERE role='STUDENT'"):List.of(user);
        var jobs=db.query("SELECT * FROM opportunities WHERE status='OPEN' AND deadline>=CURRENT_DATE");List<Double> list=new ArrayList<>();Map<Long,Map<Long,Integer>> skillCache=new HashMap<>();for(var j:jobs)skillCache.put(number(j,"id"),flow.levels(number(j,"id"),false));
        for(var student:students){var owned=flow.levels(number(student,"id"),true);for(var j:jobs)list.add(Probability.coverage(owned,skillCache.get(number(j,"id"))));}
        double[] scores=list.stream().mapToDouble(Double::doubleValue).toArray();var summary=Probability.summarize(scores);
        StringBuilder b=new StringBuilder(heading("PROBABILITY & STATISTICS","Understand the numbers","Transparent calculations, explicit sample spaces and no invented hiring probabilities.",""));
        b.append("<div class='notice'>Scope: ").append(admin?"all registered students × all open, unexpired opportunities":"your profile × all open, unexpired opportunities").append(". Academic eligibility is not used to filter this score distribution. Scores reflect self-reported skills.</div>");
        b.append("<div class='metrics'>").append(metric("Evaluated pairs",summary.count(),students.size()+" profiles × "+jobs.size()+" open roles")).append(metric("Mean coverage",f(summary.mean())+"%","Arithmetic average")).append(metric("Median coverage",f(summary.median())+"%","Middle of the ordered scores")).append(metric("Standard deviation",f(summary.standardDeviation()),"Percentage points · population")).append("</div>");
        b.append("<div class='split'><section class='panel'><h2>Empirical probability</h2><form method='get'>").append(field("Coverage threshold (%)","threshold",threshold,"number",true,"min='0' max='100' step='1'")).append("<button class='secondary'>Recalculate</button></form><div class='stat-result'>").append(scores.length==0?"No observations":pct(Probability.empirical(scores,threshold))).append("</div><p>P(coverage ≥ ").append(f(threshold)).append("%) = qualifying pairs / all evaluated pairs.</p><p>Population variance: <strong>").append(f(summary.variance())).append("</strong> squared percentage points. Variance uses N, not N−1, because this is the complete recorded population in the selected scope.</p><details><summary>How coverage is calculated</summary><p>Coverage = 100 × mean(min(1, student level / required level)) across required skills. Missing skill = 0; beginner = 1, intermediate = 2, advanced = 3. Empty requirements are reported as zero, not a perfect match.</p></details></section><section class='panel'><h2>Coverage distribution</h2><table><thead><tr><th>Coverage band</th><th>Pairs</th><th>Share</th></tr></thead><tbody>");
        for(int i=0;i<5;i++){int low=i*20,high=(i+1)*20;long count=Arrays.stream(scores).filter(s->s>=low&&(high==100?s<=100:s<high)).count();b.append("<tr><td>").append(low).append("–").append(high).append(high==100?"% (inclusive)":"% (upper exclusive)").append("</td><td>").append(count).append("</td><td>").append(scores.length==0?"—":pct(count/(double)scores.length)).append("</td></tr>");}b.append("</tbody></table></section></div>");
        String scope=admin?"":" AND user_id="+number(user,"id");
        int n=(int)number(db.one("SELECT COUNT(*) AS n FROM applications WHERE status IN ('OFFERED','ACCEPTED','DECLINED','REJECTED')"+scope),"n"),success=(int)number(db.one("SELECT COUNT(*) AS n FROM applications WHERE status IN ('OFFERED','ACCEPTED','DECLINED')"+scope),"n");
        var interval=Probability.wilson(success,n);
        b.append("<section class='panel'><h2>Observed offer outcomes</h2><p>Offer event = offered, accepted or declined. Decided set = these outcomes plus rejected. Applied, shortlisted, interview and withdrawn records are excluded. This is an observational convenience sample, not a calibrated prediction.</p><div class='metrics compact'>").append(metric("Decided applications",n,success+" received an offer")).append(metric("Observed offer rate",n==0?"No data":pct(success/(double)n),"P(offer | recorded decision)")).append(metric("Beta(1,1) posterior mean",pct(Probability.betaPosteriorMean(success,n)),n==0?"Prior only; no observed outcomes":"(offers + 1) / (decided + 2)")).append(metric("95% Wilson interval",n==0?"No estimate":pct(interval.low())+" – "+pct(interval.high()),"Binomial approximation; not a guarantee")).append("</div><p class='hint'>The Wilson interval and beta model assume independent, comparable Bernoulli outcomes. Repeated applications by a student, different companies and selection bias can violate these assumptions. Small samples are especially uncertain.</p></section>");
        int applications=App.integerDefault(p,"n",5,1,100),k=App.integerDefault(p,"k",1,0,100),trials=App.integerDefault(p,"trials",10000,100,100000);if(k>applications)throw new IllegalArgumentException("Exactly k offers cannot exceed n applications.");double probability=p.containsKey("p")?App.decimal(p,"p",0,1):0.2;long seed=42;var simulation=Probability.simulate(applications,probability,trials,seed);
        b.append("<section class='panel'><h2>What-if application simulator</h2><p>Choose a hypothetical constant offer probability p. It is <strong>not</strong> calculated from your skill score. The model assumes independent applications with the same p.</p><form method='get'><div class='form-grid'>").append(hidden("threshold",threshold)).append(field("Number of applications (n)","n",applications,"number",true,"min='1' max='100'")).append(field("Hypothetical offer probability (p)","p",probability,"number",true,"min='0' max='1' step='0.01'")).append(field("Exactly k offers","k",k,"number",true,"min='0' max='100'")).append(field("Monte Carlo trials","trials",trials,"number",true,"min='100' max='100000'")).append("</div><button>Run simulation</button></form><div class='metrics compact'>").append(metric("P(exactly "+k+" offers)",pct(Probability.binomial(applications,k,probability)),"C(n,k) p^k (1−p)^(n−k)")).append(metric("P(at least one), exact",pct(simulation.theoreticalAtLeastOne()),"1 − (1−p)^n")).append(metric("P(at least one), simulated",pct(simulation.atLeastOne()),trials+" trials · fixed seed 42")).append(metric("Mean offers, simulated",f(simulation.meanOffers()),"Theoretical E[X] = "+f(applications*probability))).append("</div><p class='hint'>A fixed seed makes the experiment reproducible. Simulation error is expected; the exact binomial result is the reference.</p></section>");
        if(admin){b.append("<section class='panel'><h2>Conditional offer rates by coverage at application</h2><p>For each score band: P(offer | decided application in this band). These descriptive associations are not causal effects.</p><table><thead><tr><th>Submission coverage</th><th>Decided</th><th>Offers</th><th>Conditional rate</th></tr></thead><tbody>");for(int i=0;i<2;i++){int low=i==0?0:60,high=i==0?60:101;var rows=db.query("SELECT status FROM applications WHERE score_at_apply>=? AND score_at_apply<? AND status IN ('OFFERED','ACCEPTED','DECLINED','REJECTED')",low,high);long offers=rows.stream().filter(r->!r.get("status").equals("REJECTED")).count();b.append("<tr><td>").append(i==0?"Below 60%":"60–100%").append("</td><td>").append(rows.size()).append("</td><td>").append(offers).append("</td><td>").append(rows.isEmpty()?"No observations":pct(offers/(double)rows.size())).append("</td></tr>");}b.append("</tbody></table></section>");}
        return b.toString();
    }
}
